package com.example.desktop;

import javafx.geometry.Insets;
import javafx.scene.Node;
import javafx.scene.control.*;
import javafx.scene.layout.*;

public final class Section32Views {
  private Section32Views(){}
  public static Node create(){
    BorderPane root=new BorderPane();VBox head=new VBox(5);head.setPadding(new Insets(18,22,10,22));
    Label h=new Label("Section 32 — Fire Alarm Systems, Smoke/CO Alarms & Fire Pumps");h.setStyle("-fx-font-size:21px;-fx-font-weight:bold;-fx-text-fill:#14213d;");
    Label s=new Label("Quick reference plus simple exam-style current calculators. Installation and device placement still depend on the applicable Building Code and CAN/ULC standards.");s.setWrapText(true);s.setStyle("-fx-text-fill:#64748b;");head.getChildren().addAll(h,s);
    TabPane tabs=new TabPane();tabs.getTabs().addAll(tab("Fire Alarm Wiring",fireAlarm()),tab("Smoke / CO",smoke()),tab("Fire Pump",firePump()),tab("EOL Calculator",eol()));root.setTop(head);root.setCenter(tabs);return root;
  }
  private static Node fireAlarm(){return page(card("Rule 32-100 — Conductors","Fire-alarm conductors are copper except where the Code specifically permits otherwise. Minimum insulation rating is 300 V, and minimum conductor sizes depend on whether they are individual conductors or integral multi-conductor assemblies."),card("Rule 32-102 — Wiring method","Fire-alarm wiring is generally installed in an enclosed raceway or suitable armoured/sheath cable, with specific allowances for combustible construction. Fire-alarm conductors are kept independent of other wiring except where connection to the supply, signal, ancillary or communication circuit requires sharing an enclosure."),card("Rule 32-104 — Bonding","Metal boxes, raceways, cabinets and exposed non-current-carrying metal parts are bonded in accordance with Section 10. Non-metallic wiring systems require the bonding conductor arrangement specified by the Code."),card("Rules 32-106 / 32-108 — Supervision and supply","Dual terminals/splice leads are independently terminated. The fire alarm system has a separate power-supply circuit; the disconnect/OCPD is permanently identified for fire alarm service, coloured red and lockable in the ON position."));}
  private static Node smoke(){return page(card("Dwelling smoke / CO alarms","CEC 2024 Rule 32-200 covers permanently connected smoke and carbon-monoxide alarms in dwelling units. They are normally supplied from a lighting circuit or a circuit supplying a mix of lighting and receptacles."),card("No ordinary local disconnect","There is no disconnecting means between the alarm and the branch-circuit OCPD. Wiring and interconnection follow Section 12."),card("GFCI / AFCI nuance","The Code generally avoids putting smoke/CO alarms on a GFCI/AFCI-protected circuit unless the alarm/device has an integral battery secondary supply as permitted by the rule."));}
  private static Node firePump(){
    TextField fire=tf("100"),jockey=tf("0"),aux=tf("0");TextArea out=new TextArea();out.setEditable(false);out.setWrapText(true);Button calc=new Button("Calculate conductor ampacity");calc.setOnAction(e->{try{double fp=n(fire),jp=n(jockey),a=n(aux),req=1.25*(fp+jp+a);out.setText("FIRE PUMP SUPPLY CONDUCTOR\n\nFire pump FLC = "+f(fp)+" A\nJockey pump FLC = "+f(jp)+" A\nAuxiliary load current = "+f(a)+" A\n\nRequired ampacity = 125% × total = "+f(req)+" A\n\nReference: CEC 2024 Rule 32-300.\n\nThis calculates conductor ampacity only. Fire-pump disconnecting means, controller, OCPD and fire-protection wiring method have their own Section 32 requirements.");}catch(Exception ex){out.setText("Check inputs: "+ex.getMessage());}});
    VBox left=new VBox(12,card("Fire pump conductor rule","For an individual fire-pump motor, the emergency-source conductors are sized to at least 125% of motor FLC. Where multiple motors/auxiliary loads are supplied, use 125% of the applicable sum."),gridCard("Inputs",grid("Fire pump FLC (A)",fire,"Jockey pump FLC (A)",jockey,"Auxiliary loads (A)",aux)),calc,card("Protection / wiring reminder","Section 32 also imposes special wiring-method and disconnect/OCPD requirements intended to preserve fire-pump operation. Do not size a normal motor branch circuit and assume it automatically satisfies the fire-pump rules."));left.setPadding(new Insets(16));SplitPane sp=new SplitPane(scroll(left),out);sp.setDividerPositions(.5);return sp;
  }
  private static Node eol(){TextField v=tf("24"),r=tf("3900");TextArea out=new TextArea();out.setEditable(false);out.setWrapText(true);Button calc=new Button("Calculate EOL current");calc.setOnAction(e->{try{double volts=n(v),ohms=n(r),amps=volts/ohms;out.setText("END-OF-LINE CURRENT\n\nI = V ÷ R\n= "+f(volts)+" V ÷ "+f(ohms)+" Ω\n= "+String.format("%.6f A",amps)+"\n= "+String.format("%.2f mA",amps*1000)+"\n\nExample: 24 V across 3.9 kΩ ≈ 6.15 mA.\n\nThis is an electrical Ohm's-law calculator, not a substitute for the fire-alarm manufacturer's supervision/EOL requirements.");}catch(Exception ex){out.setText("Check inputs: "+ex.getMessage());}});VBox left=new VBox(12,card("EOL / supervision current","Useful for practice questions that give a supervision voltage and end-of-line resistance."),gridCard("Inputs",grid("Circuit voltage (V)",v,"EOL resistance (Ω)",r)),calc);left.setPadding(new Insets(16));SplitPane sp=new SplitPane(scroll(left),out);sp.setDividerPositions(.5);return sp;}
  private static VBox page(Node... n){VBox v=new VBox(12,n);v.setPadding(new Insets(18));return v;}private static VBox card(String t,String x){Label h=new Label(t);h.setStyle("-fx-font-size:16px;-fx-font-weight:bold;");Label b=new Label(x);b.setWrapText(true);b.setStyle("-fx-text-fill:#475569;");VBox v=new VBox(7,h,b);v.setPadding(new Insets(14));v.setStyle("-fx-background-color:white;-fx-border-color:#e2e8f0;-fx-background-radius:10;-fx-border-radius:10;");return v;}private static VBox gridCard(String t,GridPane g){Label h=new Label(t);h.setStyle("-fx-font-size:16px;-fx-font-weight:bold;");VBox v=new VBox(8,h,g);v.setPadding(new Insets(14));v.setStyle("-fx-background-color:white;-fx-border-color:#e2e8f0;-fx-background-radius:10;-fx-border-radius:10;");return v;}private static GridPane grid(Object... p){GridPane g=new GridPane();g.setHgap(12);g.setVgap(8);for(int i=0;i<p.length;i+=2){g.add(new Label(String.valueOf(p[i])),0,i/2);g.add((Node)p[i+1],1,i/2);}return g;}private static ScrollPane scroll(Node n){ScrollPane s=new ScrollPane(n);s.setFitToWidth(true);return s;}private static Tab tab(String t,Node n){Tab x=new Tab(t,n);x.setClosable(false);return x;}private static TextField tf(String s){TextField t=new TextField(s);t.setMaxWidth(250);return t;}private static double n(TextField f){return Double.parseDouble(f.getText().trim());}private static String f(double d){return String.format("%.2f",d);}
}
